window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-011"]={"SAMD15":{"coreEvidence":[],"near_known_relatives":[]},"RTL5":{"coreEvidence":[],"near_known_relatives":[]},"PRR23E":{"coreEvidence":[],"near_known_relatives":[]},"SH2D7":{"coreEvidence":[],"near_known_relatives":[]},"PRRT4":{"coreEvidence":[],"near_known_relatives":[]},"CT45A6":{"coreEvidence":[{"partner":"BRD2","hgnc":"HGNC:1103","core":true,"core_annotation":{"hgnc":"HGNC:1103","symbol_at_source":"BRD2","accession":"P25440","function":"Histone modification read","target":"histone","pmids":["18406326","20495584"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":358,"hub_weight":0.35007002100700246,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader protein that specifically recognizes and binds histone H4 acetylated at 'Lys-5' and 'Lys-12' (H4K5ac and H4K12ac, respectively), thereby controlling gene expression and remodeling chromatin structures (PubMed:17148447, PubMed:17848202, PubMed:18406326, PubMed:20048151, PubMed:20709061, PubMed:20871596). Recruits transcription factors and coactivators to target gene sites, and activates RNA polymerase II machinery for transcriptional elongation (PubMed:28262505). Plays a key role in genome compartmentalization via its association with CTCF and cohesin: recruited to chromatin by CTCF and promotes formation of topologically associating domains (TADs) via its ability to bind acetylated histones, contributing to CTCF boundary formation and enhancer insulation (PubMed:35410381). Also recognizes and binds acetylated non-histone proteins, such as STAT3 (PubMed:28262505). Involved in inflammatory response by regulating differentiation of naive CD4(+) T-cells into T-helper Th17: recognizes and binds STAT3 acetylated at 'Lys-87', promoting STAT3 recruitment to chromatin (PubMed:28262505). In addition to acetylated lysines, also recognizes and binds lysine residues on histones that are both methylated and acetylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Specifically binds histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000)","source":"project UniProt records20261017/18"},{"partner":"CSNK2A1","hgnc":"HGNC:2457","core":true,"core_annotation":{"hgnc":"HGNC:2457","symbol_at_source":"CSNK2A1","accession":"P68400","function":"Histone modification","target":"histone","pmids":["24217316","22325352"],"complexes":"RING2-FBRS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":769,"hub_weight":0.2470831055537004,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of a constitutively active serine/threonine-protein kinase complex that phosphorylates a large number of substrates containing acidic residues C-terminal to the phosphorylated serine or threonine (PubMed:11239457, PubMed:11704824, PubMed:16193064, PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:19188443, PubMed:20545769, PubMed:20625391, PubMed:22017874, PubMed:22406621, PubMed:24962073, PubMed:30898438, PubMed:31439799). Regulates numerous cellular processes, such as cell cycle progression, apoptosis and transcription, as well as viral infection (PubMed:12631575, PubMed:19387551, PubMed:19387552). May act as a regulatory node which integrates and coordinates numerous signals leading to an appropriate cellular response (PubMed:12631575, PubMed:19387551, PubMed:19387552). During mitosis, functions as a component of the p53/TP53-dependent spindle assembly checkpoint (SAC) that maintains cyclin-B-CDK1 activity and G2 arrest in response to spindle damage (PubMed:11704824, PubMed:19188443). Also required for p53/TP53-mediated apoptosis, phosphorylating 'Ser-392' of p53/TP53 following UV irradiation (PubMed:11239457). Phosphorylates a number of DNA repair proteins in response to DNA damage, such as MDC1, MRE11, RAD9A, RAD51 and HTATSF1, promoting their recruitment to DNA damage sites (PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:20545769, PubMed:21482717, PubMed:22325354, PubMed:26811421, PubMed:28512243, PubMed:30898438, PubMed:35597237). Can also negatively regulate apoptosis (PubMed:16193064, PubMed:22184066). Phosphorylates the caspases CASP9 and CASP2 and the apoptotic regulator NOL3 (PubMed:16193064). Phosphorylation protects CASP9 from cleavage and activation by CASP8, and inhibits the dimerization of CASP2 and activation of CASP8 (PubMed:16193064). Phosphorylates YY1, protecting YY1 from cleavage by CASP7 during apoptosis (PubMed:22184066). Regulates transcription by direct phosphorylation of RNA polymerases I, II, III and IV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Also phosphorylates and regulates numerous transcription factors including NF-kappa-B, STAT1, CREB1, IRF1, IRF2, ATF1, ATF4, SRF, MAX, JUN, FOS, MYC and MYB (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Phosphorylates Hsp90 and its co-chaperones FKBP4 and CDC37, which is essential for chaperone function (PubMed:19387550). Mediates sequential phosphorylation of FNIP1, promoting its gradual interaction with Hsp90, leading to activate both kinase and non-kinase client proteins of Hsp90 (PubMed:30699359). Regulates Wnt signaling by phosphorylating CTNNB1 and the transcription factor LEF1 (PubMed:19387549). Acts as an ectokinase that phosphorylates several extracellular proteins (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). During viral infection, phosphorylates various proteins involved in the viral life cycles of EBV, HSV, HBV, HCV, HIV, CMV and HPV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). Phosphorylates PML at 'Ser-565' and primes it for ubiquitin-mediated degradation (PubMed:20625391, PubMed:22406621). Plays an important role in the circadian clock function by phosphorylating BMAL1 at 'Ser-90' which is pivotal for its interaction with CLOCK and which controls CLOCK nuclear entry (By similarity). Phosphorylates CCAR2 at 'Thr-454' in gastric carcinoma tissue (PubMed:24962073). Phosphorylates FMR1, promoting FMR1-dependent formation of a membraneless compartment (PubMed:30765518, PubMed:31439799). May phosphorylate histone H2A on 'Ser-1' (PubMed:38334665)","source":"project UniProt records20261017/18"},{"partner":"PPM1G","hgnc":"HGNC:9278","core":true,"core_annotation":{"hgnc":"HGNC:9278","symbol_at_source":"PPM1G","accession":"O15355","function":"Chromatin remodeling","target":"chromatin","pmids":["23723158"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":283,"hub_weight":0.3874921291460643,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"","source":"project UniProt records20261017/18"},{"partner":"PPP4C","hgnc":"HGNC:9319","core":true,"core_annotation":{"hgnc":"HGNC:9319","symbol_at_source":"PPP4C","accession":"P60510","function":"Histone modification erase","target":"histone","pmids":["18758438"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":137,"hub_weight":0.5170876899950192,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein phosphatase that is involved in many processes such as microtubule organization at centrosomes, maturation of spliceosomal snRNPs, apoptosis, DNA repair, tumor necrosis factor (TNF)-alpha signaling, activation of c-Jun N-terminal kinase MAPK8, regulation of histone acetylation, DNA damage checkpoint signaling, NF-kappa-B activation and cell migration. The PPP4C-PPP4R1 PP4 complex may play a role in dephosphorylation and regulation of HDAC3. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on Ser-140 (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Dephosphorylates NDEL1 at CDK1 phosphorylation sites and negatively regulates CDK1 activity in interphase (By similarity). In response to DNA damage, catalyzes RPA2 dephosphorylation, an essential step for DNA repair since it allows the efficient RPA2-mediated recruitment of RAD51 to chromatin","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"},{"partner":"BRD4","hgnc":"HGNC:13575","core":true,"core_annotation":{"hgnc":"HGNC:13575","symbol_at_source":"BRD4","accession":"O60885","function":"Histone modification read","target":"histone","pmids":["12840145"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1402,"hub_weight":0.18556740475630137,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Chromosome; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader protein that recognizes and binds acetylated histones and plays a key role in transmission of epigenetic memory across cell divisions and transcription regulation (PubMed:20871596, PubMed:23086925, PubMed:23317504, PubMed:29176719, PubMed:29379197). Remains associated with acetylated chromatin throughout the entire cell cycle and provides epigenetic memory for postmitotic G1 gene transcription by preserving acetylated chromatin status and maintaining high-order chromatin structure (PubMed:22334664, PubMed:23317504, PubMed:23589332). During interphase, plays a key role in regulating the transcription of signal-inducible genes by associating with the P-TEFb complex and recruiting it to promoters (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). Also recruits P-TEFb complex to distal enhancers, so called anti-pause enhancers in collaboration with JMJD6 (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). BRD4 and JMJD6 are required to form the transcriptionally active P-TEFb complex by displacing negative regulators such as HEXIM1 and 7SKsnRNA complex from P-TEFb, thereby transforming it into an active form that can then phosphorylate the C-terminal domain (CTD) of RNA polymerase II (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). Regulates differentiation of naive CD4(+) T-cells into T-helper Th17 by promoting recruitment of P-TEFb to promoters (By similarity). Promotes phosphorylation of 'Ser-2' of the C-terminal domain (CTD) of RNA polymerase II (PubMed:23086925). According to a report, directly acts as an atypical protein kinase and mediates phosphorylation of 'Ser-2' of the C-terminal domain (CTD) of RNA polymerase II; these data however need additional evidence in vivo (PubMed:22509028). In addition to acetylated histones, also recognizes and binds acetylated RELA, leading to further recruitment of the P-TEFb complex and subsequent activation of NF-kappa-B (PubMed:19103749). Also acts as a regulator of p53/TP53-mediated transcription: following phosphorylation by CK2, recruited to p53/TP53 specific target promoters (PubMed:23317504)\nActs as a chromatin insulator in the DNA damage response pathway. Inhibits DNA damage response signaling by recruiting the condensin-2 complex to acetylated histones, leading to chromatin structure remodeling, insulating the region from DNA damage response by limiting spreading of histone H2AX/H2A.x phosphorylation","source":"project UniProt records20261017/18"},{"partner":"HDAC6","hgnc":"HGNC:14064","core":true,"core_annotation":{"hgnc":"HGNC:14064","symbol_at_source":"HDAC6","accession":"Q9UBN7","function":"Histone modification erase","target":"histone","pmids":["10220385"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":618,"hub_weight":0.2735878275822914,"quality":0.65,"programmes":["pubmed:35676659"],"pmids":["35676659"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Cytoplasm, cytoskeleton; Nucleus; Perikaryon; Cell projection, dendrite; Cell projection, axon; Cell projection, cilium; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, cilium basal body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deacetylates a wide range of non-histone substrates (PubMed:12024216, PubMed:18606987, PubMed:20308065, PubMed:24882211, PubMed:26246421, PubMed:30538141, PubMed:31857589, PubMed:30770470, PubMed:38534334, PubMed:39567688). Plays a central role in microtubule-dependent cell motility by mediating deacetylation of tubulin (PubMed:12024216, PubMed:20308065, PubMed:26246421). Required for cilia disassembly via deacetylation of alpha-tubulin (PubMed:17604723, PubMed:26246421). Alpha-tubulin deacetylation results in destabilization of dynamic microtubules (By similarity). Promotes deacetylation of CTTN, leading to actin polymerization, promotion of autophagosome-lysosome fusion and completion of autophagy (PubMed:30538141). Deacetylates SQSTM1 (PubMed:31857589). Deacetylates peroxiredoxins PRDX1 and PRDX2, decreasing their reducing activity (PubMed:18606987). Deacetylates antiviral protein RIGI in the presence of viral mRNAs which is required for viral RNA detection by RIGI (By similarity). Sequentially deacetylates and polyubiquitinates DNA mismatch repair protein MSH2 which leads to MSH2 degradation, reducing cellular sensitivity to DNA-damaging agents and decreasing cellular DNA mismatch repair activities (PubMed:24882211). Deacetylates DNA mismatch repair protein MLH1 which prevents recruitment of the MutL alpha complex (formed by the MLH1-PMS2 heterodimer) to the MutS alpha complex (formed by the MSH2-MSH6 heterodimer), leading to tolerance of DNA damage (PubMed:30770470). Deacetylates RHOT1/MIRO1 which blocks mitochondrial transport and mediates axon growth inhibition (By similarity). Deacetylates transcription factor SP1 which leads to increased expression of ENG, positively regulating angiogenesis (PubMed:38534334). Deacetylates KHDRBS1/SAM68 which regulates alternative splicing by inhibiting the inclusion of CD44 alternate exons (PubMed:26080397). Deacetylates PRDM16 (By similarity). Acts as a valine sensor by binding to valine through the primate-specific SE14 repeat region (PubMed:39567688). In valine deprivation conditions, translocates from the cytoplasm to the nucleus where it deacetylates TET2 which promotes TET2-dependent DNA demethylation, leading to DNA damage (PubMed:39567688). Promotes odontoblast differentiation following IPO7-mediated nuclear import and subsequent repression of RUNX2 expression (By similarity). In addition to its protein deacetylase activity, plays a key role in the degradation of misfolded proteins: when misfolded proteins are too abundant to be degraded by the chaperone refolding system and the ubiquitin-proteasome, mediates the transport of misfolded proteins to a cytoplasmic juxtanuclear structure called aggresome (PubMed:17846173). Probably acts as an adapter that recognizes polyubiquitinated misfolded proteins and targets them to the aggresome, facilitating their clearance by autophagy (PubMed:17846173). Involved in the MTA1-mediated epigenetic regulation of ESR1 expression in breast cancer (PubMed:24413532)\n(Microbial infection) Deacetylates the SARS-CoV-2 N protein which promotes association of the viral N protein with human G3BP1, leading to disruption of cellular stress granule formation and facilitating viral replication","source":"project UniProt records20261017/18"},{"partner":"SIRT1","hgnc":"HGNC:14929","core":true,"core_annotation":{"hgnc":"HGNC:14929","symbol_at_source":"SIRT1","accession":"Q96EB6","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":["15469825"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":398,"hub_weight":0.33407655239053047,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus, PML body; Cytoplasm; Nucleus; Nucleus, nucleoplasm; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase that links transcriptional regulation directly to intracellular energetics and participates in the coordination of several separated cellular functions such as cell cycle, response to DNA damage, metabolism, apoptosis and autophagy (PubMed:11672523, PubMed:12006491, PubMed:14976264, PubMed:14980222, PubMed:15126506, PubMed:15152190, PubMed:15205477, PubMed:15469825, PubMed:15692560, PubMed:16079181, PubMed:16166628, PubMed:16892051, PubMed:16998810, PubMed:17283066, PubMed:17290224, PubMed:17334224, PubMed:17505061, PubMed:17612497, PubMed:17620057, PubMed:17936707, PubMed:18203716, PubMed:18296641, PubMed:18662546, PubMed:18687677, PubMed:19188449, PubMed:19220062, PubMed:19364925, PubMed:19690166, PubMed:19934257, PubMed:20097625, PubMed:20100829, PubMed:20203304, PubMed:20375098, PubMed:20620956, PubMed:20670893, PubMed:20817729, PubMed:20955178, PubMed:21149730, PubMed:21245319, PubMed:21471201, PubMed:21504832, PubMed:21555002, PubMed:21698133, PubMed:21701047, PubMed:21775285, PubMed:21807113, PubMed:21841822, PubMed:21890893, PubMed:21947282, PubMed:22274616, PubMed:22918831, PubMed:24415752, PubMed:24824780, PubMed:29681526, PubMed:29765047, PubMed:30409912). Can modulate chromatin function through deacetylation of histones and can promote alterations in the methylation of histones and DNA, leading to transcriptional repression (PubMed:15469825). Deacetylates a broad range of transcription factors and coregulators, thereby regulating target gene expression positively and negatively (PubMed:14976264, PubMed:14980222, PubMed:15152190). Serves as a sensor of the cytosolic ratio of NAD(+)/NADH which is altered by glucose deprivation and metabolic changes associated with caloric restriction (PubMed:15205477). Is essential in skeletal muscle cell differentiation and in response to low nutrients mediates the inhibitory effect on skeletal myoblast differentiation which also involves 5'-AMP-activated protein kinase (AMPK) and nicotinamide phosphoribosyltransferase (NAMPT) (By similarity). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871, PubMed:21504832). Deacetylates 'Lys-266' of SUV39H1, leading to its activation (PubMed:21504832). Inhibits skeletal muscle differentiation by deacetylating PCAF and MYOD1 (PubMed:19188449). Deacetylates H2A and 'Lys-26' of H1-4 (PubMed:15469825). Deacetylates 'Lys-16' of histone H4 (in vitro). Involved in NR0B2/SHP corepression function through chromatin remodeling: Recruited to LRH1 target gene promoters by NR0B2/SHP thereby stimulating histone H3 and H4 deacetylation leading to transcriptional repression (PubMed:20375098). Proposed to contribute to genomic integrity via positive regulation of telomere length; however, reports on localization to pericentromeric heterochromatin are conflicting (By similarity). Proposed to play a role in constitutive heterochromatin (CH) formation and/or maintenance through regulation of the available pool of nuclear SUV39H1 (PubMed:15469825, PubMed:18004385). Upon oxidative/metabolic stress decreases SUV39H1 degradation by inhibiting SUV39H1 polyubiquitination by MDM2 (PubMed:18004385, PubMed:21504832). This increase in SUV39H1 levels enhances SUV39H1 turnover in CH, which in turn seems to accelerate renewal of the heterochromatin which correlates with greater genomic integrity during stress response (PubMed:18004385, PubMed:21504832). Deacetylates 'Lys-382' of p53/TP53 and impairs its ability to induce transcription-dependent proapoptotic program and modulate cell senescence (PubMed:11672523, PubMed:12006491, PubMed:22542455). Deacetylates TAF1B and thereby represses rDNA transcription by the RNA polymerase I (By similarity). Deacetylates MYC, promotes the association of MYC with MAX and decreases MYC stability leading to compromised transformational capability (PubMed:19364925, PubMed:21807113). Deacetylates FOXO3 in response to oxidative stress thereby increasing its ability to induce cell cycle arrest and resistance to oxidative stress but inhibiting FOXO3-mediated induction of apoptosis transcriptional activity; also leading to FOXO3 ubiquitination and protesomal degradation (PubMed:14976264, PubMed:14980222, PubMed:21841822). Appears to have a similar effect on MLLT7/FOXO4 in regulation of transcriptional activity and apoptosis (PubMed:15126506). Deacetylates DNMT1; thereby impairs DNMT1 methyltransferase-independent transcription repressor activity, modulates DNMT1 cell cycle regulatory function and DNMT1-mediated gene silencing (PubMed:21947282). Deacetylates RELA/NF-kappa-B p65 thereby inhibiting its transactivating potential and augments apoptosis in response to TNF (PubMed:15152190). Deacetylates HIF1A, KAT5/TIP60, RB1 and HIC1 (PubMed:17283066, PubMed:17620057, PubMed:20100829, PubMed:20620956). Deacetylates FOXO1 resulting in its nuclear retention and enhancement of its transcriptional activity leading to increased gluconeogenesis in liver (PubMed:15692560). Inhibits E2F1 transcriptional activity and apoptotic function, possibly by deacetylation (PubMed:16892051). Involved in HES1- and HEY2-mediated transcriptional repression (PubMed:12535671). In cooperation with MYCN seems to be involved in transcriptional repression of DUSP6/MAPK3 leading to MYCN stabilization by phosphorylation at 'Ser-62' (PubMed:21698133). Deacetylates MEF2D (PubMed:16166628). Required for antagonist-mediated transcription suppression of AR-dependent genes which may be linked to local deacetylation of histone H3 (PubMed:17505061). Represses HNF1A-mediated transcription (By similarity). Required for the repression of ESRRG by CREBZF (PubMed:19690166). Deacetylates NR1H3 and NR1H2 and deacetylation of NR1H3 at 'Lys-434' positively regulates transcription of NR1H3:RXR target genes, promotes NR1H3 proteasomal degradation and results in cholesterol efflux; a promoter clearing mechanism after reach round of transcription is proposed (PubMed:17936707). Involved in lipid metabolism: deacetylates LPIN1, thereby inhibiting diacylglycerol synthesis (PubMed:20817729, PubMed:29765047). Implicated in regulation of adipogenesis and fat mobilization in white adipocytes by repression of PPARG which probably involves association with NCOR1 and SMRT/NCOR2 (By similarity). Deacetylates p300/EP300 and PRMT1 (By similarity). Deacetylates ACSS2 leading to its activation, and HMGCS1 deacetylation (PubMed:21701047). Involved in liver and muscle metabolism. Through deacetylation and activation of PPARGC1A is required to activate fatty acid oxidation in skeletal muscle under low-glucose conditions and is involved in glucose homeostasis (PubMed:23142079). Involved in regulation of PPARA and fatty acid beta-oxidation in liver. Involved in positive regulation of insulin secretion in pancreatic beta cells in response to glucose; the function seems to imply transcriptional repression of UCP2. Proposed to deacetylate IRS2 thereby facilitating its insulin-induced tyrosine phosphorylation. Deacetylates SREBF1 isoform SREBP-1C thereby decreasing its stability and transactivation in lipogenic gene expression (PubMed:17290224, PubMed:20817729). Involved in DNA damage response by repressing genes which are involved in DNA repair, such as XPC and TP73, deacetylating XRCC6/Ku70, and facilitating recruitment of additional factors to sites of damaged DNA, such as SIRT1-deacetylated NBN can recruit ATM to initiate DNA repair and SIRT1-deacetylated XPA interacts with RPA2 (PubMed:15205477, PubMed:16998810, PubMed:17334224, PubMed:17612497, PubMed:20670893, PubMed:21149730). Also involved in DNA repair of DNA double-strand breaks by homologous recombination and specifically single-strand annealing independently of XRCC6/Ku70 and NBN (PubMed:15205477, PubMed:17334224, PubMed:20097625). Promotes DNA double-strand breaks by mediating deacetylation of SIRT6 (PubMed:32538779). Transcriptional suppression of XPC probably involves an E2F4:RBL2 suppressor complex and protein kinase B (AKT) signaling. Transcriptional suppression of TP73 probably involves E2F4 and PCAF. Deacetylates WRN thereby regulating its helicase and exonuclease activities and regulates WRN nuclear translocation in response to DNA damage (PubMed:18203716). Deacetylates APEX1 at 'Lys-6' and 'Lys-7' and stimulates cellular AP endonuclease activity by promoting the association of APEX1 to XRCC1 (PubMed:19934257). Catalyzes deacetylation of ERCC4/XPF, thereby impairing interaction with ERCC1 and nucleotide excision repair (NER) (PubMed:32034146). Increases p53/TP53-mediated transcription-independent apoptosis by blocking nuclear translocation of cytoplasmic p53/TP53 and probably redirecting it to mitochondria. Deacetylates XRCC6/Ku70 at 'Lys-539' and 'Lys-542' causing it to sequester BAX away from mitochondria thereby inhibiting stress-induced apoptosis. Is involved in autophagy, presumably by deacetylating ATG5, ATG7 and MAP1LC3B/ATG8 (PubMed:18296641). Deacetylates AKT1 which leads to enhanced binding of AKT1 and PDK1 to PIP3 and promotes their activation (PubMed:21775285). Acts as a regulator of AMPK activity in response to calorie restriction: deacetylates the ATP6V1E1 subunit of the V-ATPase complex following activation by TULP3, leading to (1) V-ATPase complex inhibition on lysosomes and (2) AMPK activation via the AXIN1-STK11/LKB1 axis (By similarity). Proposed to play role in regulation of STK11/LBK1-dependent AMPK signaling pathways implicated in cellular senescence which seems to involve the regulation of the acetylation status of STK11/LBK1. Can deacetylate STK11/LBK1 and thereby increase its activity, cytoplasmic localization and association with STRAD; however, the relevance of such activity in normal cells is unclear (PubMed:18687677, PubMed:20203304). In endothelial cells is shown to inhibit STK11/LBK1 activity and to promote its degradation. Deacetylates SMAD7 at 'Lys-64' and 'Lys-70' thereby promoting its degradation. Deacetylates CIITA and augments its MHC class II transactivation and contributes to its stability (PubMed:21890893). Deacetylates MECOM/EVI1 (PubMed:21555002). Deacetylates PML at 'Lys-487' and this deacetylation promotes PML control of PER2 nuclear localization (PubMed:22274616). During the neurogenic transition, represses selective NOTCH1-target genes through histone deacetylation in a BCL6-dependent manner and leading to neuronal differentiation. Regulates the circadian expression of several core clock genes, including BMAL1, RORC, PER2 and CRY1 and plays a critical role in maintaining a controlled rhythmicity in histone acetylation, thereby contributing to circadian chromatin remodeling (PubMed:18662546). Deacetylates BMAL1 and histones at the circadian gene promoters in order to facilitate repression by inhibitory components of the circadian oscillator (By similarity). Deacetylates PER2, facilitating its ubiquitination and degradation by the proteasome (By similarity). Protects cardiomyocytes against palmitate-induced apoptosis (By similarity). Deacetylates XBP1 isoform 2; deacetylation decreases protein stability of XBP1 isoform 2 and inhibits its transcriptional activity (PubMed:20955178). Deacetylates PCK1 and directs its activity toward phosphoenolpyruvate production promoting gluconeogenesis (PubMed:30193097). Involved in the CCAR2-mediated regulation of PCK1 and NR1D1 (PubMed:24415752). Deacetylates CTNB1 at 'Lys-49' (PubMed:24824780). In POMC (pro-opiomelanocortin) neurons, required for leptin-induced activation of PI3K signaling (By similarity). Deacetylates SOX9; promoting SOX9 nuclear localization and transactivation activity (By similarity). Involved in the regulation of centrosome duplication: deacetylates CENATAC in G1 phase, allowing for SASS6 accumulation on the centrosome and subsequent procentriole assembly (PubMed:31722219). Deacetylates NDC80/HEC1 (PubMed:30409912). In addition to protein deacetylase activity, also acts as a protein-lysine deacylase by mediating protein delactylation, depropionylation and decrotonylation (PubMed:28497810, PubMed:38512451). Mediates depropionylation of Osterix (SP7) (By similarity). Catalyzes decrotonylation of histones; it however does not represent a major histone decrotonylase (PubMed:28497810). Mediates protein delactylation of TEAD1 and YAP1 (PubMed:38512451)\nDeacetylates 'Lys-382' of p53/TP53, however with lower activity than isoform 1. In combination, the two isoforms exert an additive effect. Isoform 2 regulates p53/TP53 expression and cellular stress response and is in turn repressed by p53/TP53 presenting a SIRT1 isoform-dependent auto-regulatory loop\nCatalytically inactive 75SirT1 may be involved in regulation of apoptosis. May be involved in protecting chondrocytes from apoptotic death by associating with cytochrome C and interfering with apoptosome assembly\n(Microbial infection) In case of HIV-1 infection, interacts with and deacetylates the viral Tat protein. The viral Tat protein inhibits SIRT1 deacetylation activity toward RELA/NF-kappa-B p65, thereby potentiates its transcriptional activity and SIRT1 is proposed to contribute to T-cell hyperactivation during infection","source":"project UniProt records20261017/18"},{"partner":"SPEN","hgnc":"HGNC:17575","core":true,"core_annotation":{"hgnc":"HGNC:17575","symbol_at_source":"SPEN","accession":"Q96T58","function":"Histone modification erase cofactor, TF","target":"histone","pmids":["11331609"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":136,"hub_weight":0.5184758473652126,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May serve as a nuclear matrix platform that organizes and integrates transcriptional responses. In osteoblasts, supports transcription activation: synergizes with RUNX2 to enhance FGFR2-mediated activation of the osteocalcin FGF-responsive element (OCFRE) (By similarity). Has also been shown to be an essential corepressor protein, which probably regulates different key pathways such as the Notch pathway. Negative regulator of the Notch pathway via its interaction with RBPSUH, which prevents the association between NOTCH1 and RBPSUH, and therefore suppresses the transactivation activity of Notch signaling. Blocks the differentiation of precursor B-cells into marginal zone B-cells. Probably represses transcription via the recruitment of large complexes containing histone deacetylase proteins. May bind both to DNA and RNA","source":"project UniProt records20261017/18"},{"partner":"PPP4R2","hgnc":"HGNC:18296","core":true,"core_annotation":{"hgnc":"HGNC:18296","symbol_at_source":"PPP4R2","accession":"Q9NY27","function":"Histone modification cofactor","target":"histone","pmids":["18614045"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":93,"hub_weight":0.5913123959890826,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers. Its interaction with the SMN complex leads to enhance the temporal localization of snRNPs, suggesting a role of PPP4C in maturation of spliceosomal snRNPs. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Mediates RPA2 dephosphorylation by recruiting PPP4C to RPA2 in a DNA damage-dependent manner. RPA2 dephosphorylation is required for the efficient RPA2-mediated recruitment of RAD51 to chromatin following double strand breaks, an essential step for DNA repair","source":"project UniProt records20261017/18"},{"partner":"JMJD6","hgnc":"HGNC:19355","core":true,"core_annotation":{"hgnc":"HGNC:19355","symbol_at_source":"JMJD6","accession":"Q6NYC1","function":"Histone modification erase","target":"histone","pmids":["17947579"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":197,"hub_weight":0.44992127066584753,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus, nucleoplasm; Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Dioxygenase that can both act as a arginine demethylase and a lysyl-hydroxylase (PubMed:17947579, PubMed:20684070, PubMed:21060799, PubMed:22189873, PubMed:24498420). Acts as a lysyl-hydroxylase that catalyzes 5-hydroxylation on specific lysine residues of target proteins such as U2AF2/U2AF65 and LUC7L2. Regulates RNA splicing by mediating 5-hydroxylation of U2AF2/U2AF65, affecting the pre-mRNA splicing activity of U2AF2/U2AF65 (PubMed:19574390). Hydroxylates its own N-terminus, which is required for homooligomerization (PubMed:22189873). Plays a role in the regulation of nucleolar liquid-liquid phase separation (LLPS) by post-translationally modifying LIAT1 at its lysine-rich domain which inhibits LIAT1 nucleolar targeting (By similarity). In addition to peptidyl-lysine 5-dioxygenase activity, may act as an RNA hydroxylase, as suggested by its ability to bind single strand RNA (PubMed:20679243, PubMed:29176719). Also acts as an arginine demethylase which preferentially demethylates asymmetric dimethylation (PubMed:17947579, PubMed:24360279, PubMed:24498420). Demethylates histone H3 at 'Arg-2' (H3R2me) and histone H4 at 'Arg-3' (H4R3me), including mono-, symmetric di- and asymmetric dimethylated forms, thereby playing a role in histone code (PubMed:17947579, PubMed:24360279). However, histone arginine demethylation may not constitute the primary activity in vivo (PubMed:17947579, PubMed:21060799, PubMed:22189873). In collaboration with BRD4, interacts with the positive transcription elongation factor b (P-TEFb) complex in its active form to regulate polymerase II promoter-proximal pause release for transcriptional activation of a large cohort of genes. On distal enhancers, so called anti-pause enhancers, demethylates both histone H4R3me2 and the methyl cap of 7SKsnRNA leading to the dismissal of the 7SKsnRNA:HEXIM1 inhibitor complex. After removal of repressive marks, the complex BRD4:JMJD6 attract and retain the P-TEFb complex on chromatin, leading to its activation, promoter-proximal polymerase II pause release, and transcriptional activation (PubMed:24360279). Demethylates other arginine methylated-proteins such as ESR1 (PubMed:24498420). Has no histone lysine demethylase activity (PubMed:21060799). Required for differentiation of multiple organs during embryogenesis. Acts as a key regulator of hematopoietic differentiation: required for angiogenic sprouting by regulating the pre-mRNA splicing activity of U2AF2/U2AF65 (By similarity). Seems to be necessary for the regulation of macrophage cytokine responses (PubMed:15622002)","source":"project UniProt records20261017/18"},{"partner":"CHD8","hgnc":"HGNC:20153","core":true,"core_annotation":{"hgnc":"HGNC:20153","symbol_at_source":"CHD8","accession":"Q9HCK8","function":"Chromatin remodeling","target":"chromatin","pmids":["18378692"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":375,"hub_weight":0.3429971702850177,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor, it slides nucleosomes along DNA; nucleosome sliding requires ATP (PubMed:28533432). Acts as a transcription repressor by remodeling chromatin structure and recruiting histone H1 to target genes. Suppresses p53/TP53-mediated apoptosis by recruiting histone H1 and preventing p53/TP53 transactivation activity. Acts as a negative regulator of Wnt signaling pathway by regulating beta-catenin (CTNNB1) activity. Negatively regulates CTNNB1-targeted gene expression by being recruited specifically to the promoter regions of several CTNNB1 responsive genes. Involved in both enhancer blocking and epigenetic remodeling at chromatin boundary via its interaction with CTCF. Acts as a suppressor of STAT3 activity by suppressing the LIF-induced STAT3 transcriptional activity. Also acts as a transcription activator via its interaction with ZNF143 by participating in efficient U6 RNA polymerase III transcription. Regulates alternative splicing of a core group of genes involved in neuronal differentiation, cell cycle and DNA repair. Enables H3K36me3-coupled transcription elongation and co-transcriptional RNA processing likely via interaction with HNRNPL","source":"project UniProt records20261017/18"},{"partner":"PPP4R3A","hgnc":"HGNC:20219","core":true,"core_annotation":{"hgnc":"HGNC:20219","symbol_at_source":"SMEK1","accession":"Q6IN85","function":"Histone modification erase cofactor","target":"histone","pmids":["18614045"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":142,"hub_weight":0.5103103630798288,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4. May regulate the activity of PPP4C at centrosomal microtubule organizing centers. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA DSB repair","source":"project UniProt records20261017/18"},{"partner":"PHF14","hgnc":"HGNC:22203","core":true,"core_annotation":{"hgnc":"HGNC:22203","symbol_at_source":"PHF14","accession":"O94880","function":"Histone modification read","target":"histone","pmids":["23688586"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone-binding protein (PubMed:23688586). Binds preferentially to unmodified histone H3 but can also bind to a lesser extent to histone H3 trimethylated at 'Lys-9' (H3K9me3) as well as to histone H3 monomethylated at 'Lys-27' (H3K27ac) and trimethylated at 'Lys-27' (H3K27me3) (By similarity). Represses PDGFRA expression, thus playing a role in regulation of mesenchymal cell proliferation (By similarity). Suppresses the expression of CDKN1A/p21 by reducing the level of trimethylation of histone H3 'Lys-4', leading to enhanced proliferation of germinal center B cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CXXC1","hgnc":"HGNC:24343","core":true,"core_annotation":{"hgnc":"HGNC:24343","symbol_at_source":"CXXC1","accession":"Q9P0U4","function":"Chromatin remodeling, TF","target":"DNA","pmids":["21407193"],"complexes":"COMPASS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":110,"hub_weight":0.5590169943749475,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus speckle; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional activator that exhibits a unique DNA binding specificity for CpG unmethylated motifs with a preference for CpGG","source":"project UniProt records20261017/18"},{"partner":"CHD9","hgnc":"HGNC:25701","core":true,"core_annotation":{"hgnc":"HGNC:25701","symbol_at_source":"CHD9","accession":"Q3L8U1","function":"Chromatin remodeling","target":"DNA","pmids":["16554032"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":64,"hub_weight":0.6622661785325219,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Probable ATP-dependent chromatin-remodeling factor. Acts as a transcriptional coactivator for PPARA and possibly other nuclear receptors. Has DNA-dependent ATPase activity and binds to A/T-rich DNA. Associates with A/T-rich regulatory regions in promoters of genes that participate in the differentiation of progenitors during osteogenesis (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SETD1A","hgnc":"HGNC:29010","core":true,"core_annotation":{"hgnc":"HGNC:29010","symbol_at_source":"SETD1A","accession":"O15047","function":"Histone modification write","target":"histone","pmids":["17355966"],"complexes":"COMPASS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":140,"hub_weight":0.512989176042577,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus speckle; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that catalyzes methyl group transfer from S-adenosyl-L-methionine to the epsilon-amino group of 'Lys-4' of histone H3 (H3K4) via a non-processive mechanism (PubMed:12670868, PubMed:25561738). Part of chromatin remodeling machinery, forms H3K4me1, H3K4me2 and H3K4me3 methylation marks at active chromatin sites where transcription and DNA repair take place (PubMed:29937342, PubMed:31197650, PubMed:32346159). Responsible for H3K4me3 enriched promoters and transcriptional programming of inner mass stem cells and neuron progenitors during embryogenesis (By similarity) (PubMed:31197650). Required for H3K4me1 mark at stalled replication forks. Mediates FANCD2-dependent nucleosome remodeling and RAD51 nucleofilaments stabilization at reversed forks, protecting them from nucleolytic degradation (PubMed:29937342, PubMed:32346159). Does not methylate 'Lys-4' of histone H3 if the neighboring 'Lys-9' residue is already methylated (PubMed:12670868). Binds RNAs involved in RNA processing and the DNA damage response (PubMed:38003223)","source":"project UniProt records20261017/18"},{"partner":"PPP4R3B","hgnc":"HGNC:29267","core":true,"core_annotation":{"hgnc":"HGNC:29267","symbol_at_source":"SMEK2","accession":"Q5MIZ7","function":"Histone modification erase cofactor","target":"histone","pmids":["18614045"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":58,"hub_weight":0.6804138174397717,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"CT45A1","accession":"Q5HYN5","identity":0.989,"qcov":1.0,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"CT45A5":{"coreEvidence":[{"partner":"BRD2","hgnc":"HGNC:1103","core":true,"core_annotation":{"hgnc":"HGNC:1103","symbol_at_source":"BRD2","accession":"P25440","function":"Histone modification read","target":"histone","pmids":["18406326","20495584"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":358,"hub_weight":0.35007002100700246,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader protein that specifically recognizes and binds histone H4 acetylated at 'Lys-5' and 'Lys-12' (H4K5ac and H4K12ac, respectively), thereby controlling gene expression and remodeling chromatin structures (PubMed:17148447, PubMed:17848202, PubMed:18406326, PubMed:20048151, PubMed:20709061, PubMed:20871596). Recruits transcription factors and coactivators to target gene sites, and activates RNA polymerase II machinery for transcriptional elongation (PubMed:28262505). Plays a key role in genome compartmentalization via its association with CTCF and cohesin: recruited to chromatin by CTCF and promotes formation of topologically associating domains (TADs) via its ability to bind acetylated histones, contributing to CTCF boundary formation and enhancer insulation (PubMed:35410381). Also recognizes and binds acetylated non-histone proteins, such as STAT3 (PubMed:28262505). Involved in inflammatory response by regulating differentiation of naive CD4(+) T-cells into T-helper Th17: recognizes and binds STAT3 acetylated at 'Lys-87', promoting STAT3 recruitment to chromatin (PubMed:28262505). In addition to acetylated lysines, also recognizes and binds lysine residues on histones that are both methylated and acetylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Specifically binds histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000)","source":"project UniProt records20261017/18"},{"partner":"CSNK2A1","hgnc":"HGNC:2457","core":true,"core_annotation":{"hgnc":"HGNC:2457","symbol_at_source":"CSNK2A1","accession":"P68400","function":"Histone modification","target":"histone","pmids":["24217316","22325352"],"complexes":"RING2-FBRS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":769,"hub_weight":0.2470831055537004,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of a constitutively active serine/threonine-protein kinase complex that phosphorylates a large number of substrates containing acidic residues C-terminal to the phosphorylated serine or threonine (PubMed:11239457, PubMed:11704824, PubMed:16193064, PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:19188443, PubMed:20545769, PubMed:20625391, PubMed:22017874, PubMed:22406621, PubMed:24962073, PubMed:30898438, PubMed:31439799). Regulates numerous cellular processes, such as cell cycle progression, apoptosis and transcription, as well as viral infection (PubMed:12631575, PubMed:19387551, PubMed:19387552). May act as a regulatory node which integrates and coordinates numerous signals leading to an appropriate cellular response (PubMed:12631575, PubMed:19387551, PubMed:19387552). During mitosis, functions as a component of the p53/TP53-dependent spindle assembly checkpoint (SAC) that maintains cyclin-B-CDK1 activity and G2 arrest in response to spindle damage (PubMed:11704824, PubMed:19188443). Also required for p53/TP53-mediated apoptosis, phosphorylating 'Ser-392' of p53/TP53 following UV irradiation (PubMed:11239457). Phosphorylates a number of DNA repair proteins in response to DNA damage, such as MDC1, MRE11, RAD9A, RAD51 and HTATSF1, promoting their recruitment to DNA damage sites (PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:20545769, PubMed:21482717, PubMed:22325354, PubMed:26811421, PubMed:28512243, PubMed:30898438, PubMed:35597237). Can also negatively regulate apoptosis (PubMed:16193064, PubMed:22184066). Phosphorylates the caspases CASP9 and CASP2 and the apoptotic regulator NOL3 (PubMed:16193064). Phosphorylation protects CASP9 from cleavage and activation by CASP8, and inhibits the dimerization of CASP2 and activation of CASP8 (PubMed:16193064). Phosphorylates YY1, protecting YY1 from cleavage by CASP7 during apoptosis (PubMed:22184066). Regulates transcription by direct phosphorylation of RNA polymerases I, II, III and IV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Also phosphorylates and regulates numerous transcription factors including NF-kappa-B, STAT1, CREB1, IRF1, IRF2, ATF1, ATF4, SRF, MAX, JUN, FOS, MYC and MYB (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Phosphorylates Hsp90 and its co-chaperones FKBP4 and CDC37, which is essential for chaperone function (PubMed:19387550). Mediates sequential phosphorylation of FNIP1, promoting its gradual interaction with Hsp90, leading to activate both kinase and non-kinase client proteins of Hsp90 (PubMed:30699359). Regulates Wnt signaling by phosphorylating CTNNB1 and the transcription factor LEF1 (PubMed:19387549). Acts as an ectokinase that phosphorylates several extracellular proteins (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). During viral infection, phosphorylates various proteins involved in the viral life cycles of EBV, HSV, HBV, HCV, HIV, CMV and HPV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). Phosphorylates PML at 'Ser-565' and primes it for ubiquitin-mediated degradation (PubMed:20625391, PubMed:22406621). Plays an important role in the circadian clock function by phosphorylating BMAL1 at 'Ser-90' which is pivotal for its interaction with CLOCK and which controls CLOCK nuclear entry (By similarity). Phosphorylates CCAR2 at 'Thr-454' in gastric carcinoma tissue (PubMed:24962073). Phosphorylates FMR1, promoting FMR1-dependent formation of a membraneless compartment (PubMed:30765518, PubMed:31439799). May phosphorylate histone H2A on 'Ser-1' (PubMed:38334665)","source":"project UniProt records20261017/18"},{"partner":"PPM1G","hgnc":"HGNC:9278","core":true,"core_annotation":{"hgnc":"HGNC:9278","symbol_at_source":"PPM1G","accession":"O15355","function":"Chromatin remodeling","target":"chromatin","pmids":["23723158"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":283,"hub_weight":0.3874921291460643,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"","source":"project UniProt records20261017/18"},{"partner":"PPP4C","hgnc":"HGNC:9319","core":true,"core_annotation":{"hgnc":"HGNC:9319","symbol_at_source":"PPP4C","accession":"P60510","function":"Histone modification erase","target":"histone","pmids":["18758438"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":137,"hub_weight":0.5170876899950192,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein phosphatase that is involved in many processes such as microtubule organization at centrosomes, maturation of spliceosomal snRNPs, apoptosis, DNA repair, tumor necrosis factor (TNF)-alpha signaling, activation of c-Jun N-terminal kinase MAPK8, regulation of histone acetylation, DNA damage checkpoint signaling, NF-kappa-B activation and cell migration. The PPP4C-PPP4R1 PP4 complex may play a role in dephosphorylation and regulation of HDAC3. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on Ser-140 (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Dephosphorylates NDEL1 at CDK1 phosphorylation sites and negatively regulates CDK1 activity in interphase (By similarity). In response to DNA damage, catalyzes RPA2 dephosphorylation, an essential step for DNA repair since it allows the efficient RPA2-mediated recruitment of RAD51 to chromatin","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"},{"partner":"BRD4","hgnc":"HGNC:13575","core":true,"core_annotation":{"hgnc":"HGNC:13575","symbol_at_source":"BRD4","accession":"O60885","function":"Histone modification read","target":"histone","pmids":["12840145"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1402,"hub_weight":0.18556740475630137,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader protein that recognizes and binds acetylated histones and plays a key role in transmission of epigenetic memory across cell divisions and transcription regulation (PubMed:20871596, PubMed:23086925, PubMed:23317504, PubMed:29176719, PubMed:29379197). Remains associated with acetylated chromatin throughout the entire cell cycle and provides epigenetic memory for postmitotic G1 gene transcription by preserving acetylated chromatin status and maintaining high-order chromatin structure (PubMed:22334664, PubMed:23317504, PubMed:23589332). During interphase, plays a key role in regulating the transcription of signal-inducible genes by associating with the P-TEFb complex and recruiting it to promoters (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). Also recruits P-TEFb complex to distal enhancers, so called anti-pause enhancers in collaboration with JMJD6 (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). BRD4 and JMJD6 are required to form the transcriptionally active P-TEFb complex by displacing negative regulators such as HEXIM1 and 7SKsnRNA complex from P-TEFb, thereby transforming it into an active form that can then phosphorylate the C-terminal domain (CTD) of RNA polymerase II (PubMed:16109376, PubMed:16109377, PubMed:19596240, PubMed:23589332, PubMed:24360279). Regulates differentiation of naive CD4(+) T-cells into T-helper Th17 by promoting recruitment of P-TEFb to promoters (By similarity). Promotes phosphorylation of 'Ser-2' of the C-terminal domain (CTD) of RNA polymerase II (PubMed:23086925). According to a report, directly acts as an atypical protein kinase and mediates phosphorylation of 'Ser-2' of the C-terminal domain (CTD) of RNA polymerase II; these data however need additional evidence in vivo (PubMed:22509028). In addition to acetylated histones, also recognizes and binds acetylated RELA, leading to further recruitment of the P-TEFb complex and subsequent activation of NF-kappa-B (PubMed:19103749). Also acts as a regulator of p53/TP53-mediated transcription: following phosphorylation by CK2, recruited to p53/TP53 specific target promoters (PubMed:23317504)\nActs as a chromatin insulator in the DNA damage response pathway. Inhibits DNA damage response signaling by recruiting the condensin-2 complex to acetylated histones, leading to chromatin structure remodeling, insulating the region from DNA damage response by limiting spreading of histone H2AX/H2A.x phosphorylation","source":"project UniProt records20261017/18"},{"partner":"SIRT1","hgnc":"HGNC:14929","core":true,"core_annotation":{"hgnc":"HGNC:14929","symbol_at_source":"SIRT1","accession":"Q96EB6","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":["15469825"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":398,"hub_weight":0.33407655239053047,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus, PML body; Cytoplasm; Nucleus; Nucleus, nucleoplasm; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase that links transcriptional regulation directly to intracellular energetics and participates in the coordination of several separated cellular functions such as cell cycle, response to DNA damage, metabolism, apoptosis and autophagy (PubMed:11672523, PubMed:12006491, PubMed:14976264, PubMed:14980222, PubMed:15126506, PubMed:15152190, PubMed:15205477, PubMed:15469825, PubMed:15692560, PubMed:16079181, PubMed:16166628, PubMed:16892051, PubMed:16998810, PubMed:17283066, PubMed:17290224, PubMed:17334224, PubMed:17505061, PubMed:17612497, PubMed:17620057, PubMed:17936707, PubMed:18203716, PubMed:18296641, PubMed:18662546, PubMed:18687677, PubMed:19188449, PubMed:19220062, PubMed:19364925, PubMed:19690166, PubMed:19934257, PubMed:20097625, PubMed:20100829, PubMed:20203304, PubMed:20375098, PubMed:20620956, PubMed:20670893, PubMed:20817729, PubMed:20955178, PubMed:21149730, PubMed:21245319, PubMed:21471201, PubMed:21504832, PubMed:21555002, PubMed:21698133, PubMed:21701047, PubMed:21775285, PubMed:21807113, PubMed:21841822, PubMed:21890893, PubMed:21947282, PubMed:22274616, PubMed:22918831, PubMed:24415752, PubMed:24824780, PubMed:29681526, PubMed:29765047, PubMed:30409912). Can modulate chromatin function through deacetylation of histones and can promote alterations in the methylation of histones and DNA, leading to transcriptional repression (PubMed:15469825). Deacetylates a broad range of transcription factors and coregulators, thereby regulating target gene expression positively and negatively (PubMed:14976264, PubMed:14980222, PubMed:15152190). Serves as a sensor of the cytosolic ratio of NAD(+)/NADH which is altered by glucose deprivation and metabolic changes associated with caloric restriction (PubMed:15205477). Is essential in skeletal muscle cell differentiation and in response to low nutrients mediates the inhibitory effect on skeletal myoblast differentiation which also involves 5'-AMP-activated protein kinase (AMPK) and nicotinamide phosphoribosyltransferase (NAMPT) (By similarity). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871, PubMed:21504832). Deacetylates 'Lys-266' of SUV39H1, leading to its activation (PubMed:21504832). Inhibits skeletal muscle differentiation by deacetylating PCAF and MYOD1 (PubMed:19188449). Deacetylates H2A and 'Lys-26' of H1-4 (PubMed:15469825). Deacetylates 'Lys-16' of histone H4 (in vitro). Involved in NR0B2/SHP corepression function through chromatin remodeling: Recruited to LRH1 target gene promoters by NR0B2/SHP thereby stimulating histone H3 and H4 deacetylation leading to transcriptional repression (PubMed:20375098). Proposed to contribute to genomic integrity via positive regulation of telomere length; however, reports on localization to pericentromeric heterochromatin are conflicting (By similarity). Proposed to play a role in constitutive heterochromatin (CH) formation and/or maintenance through regulation of the available pool of nuclear SUV39H1 (PubMed:15469825, PubMed:18004385). Upon oxidative/metabolic stress decreases SUV39H1 degradation by inhibiting SUV39H1 polyubiquitination by MDM2 (PubMed:18004385, PubMed:21504832). This increase in SUV39H1 levels enhances SUV39H1 turnover in CH, which in turn seems to accelerate renewal of the heterochromatin which correlates with greater genomic integrity during stress response (PubMed:18004385, PubMed:21504832). Deacetylates 'Lys-382' of p53/TP53 and impairs its ability to induce transcription-dependent proapoptotic program and modulate cell senescence (PubMed:11672523, PubMed:12006491, PubMed:22542455). Deacetylates TAF1B and thereby represses rDNA transcription by the RNA polymerase I (By similarity). Deacetylates MYC, promotes the association of MYC with MAX and decreases MYC stability leading to compromised transformational capability (PubMed:19364925, PubMed:21807113). Deacetylates FOXO3 in response to oxidative stress thereby increasing its ability to induce cell cycle arrest and resistance to oxidative stress but inhibiting FOXO3-mediated induction of apoptosis transcriptional activity; also leading to FOXO3 ubiquitination and protesomal degradation (PubMed:14976264, PubMed:14980222, PubMed:21841822). Appears to have a similar effect on MLLT7/FOXO4 in regulation of transcriptional activity and apoptosis (PubMed:15126506). Deacetylates DNMT1; thereby impairs DNMT1 methyltransferase-independent transcription repressor activity, modulates DNMT1 cell cycle regulatory function and DNMT1-mediated gene silencing (PubMed:21947282). Deacetylates RELA/NF-kappa-B p65 thereby inhibiting its transactivating potential and augments apoptosis in response to TNF (PubMed:15152190). Deacetylates HIF1A, KAT5/TIP60, RB1 and HIC1 (PubMed:17283066, PubMed:17620057, PubMed:20100829, PubMed:20620956). Deacetylates FOXO1 resulting in its nuclear retention and enhancement of its transcriptional activity leading to increased gluconeogenesis in liver (PubMed:15692560). Inhibits E2F1 transcriptional activity and apoptotic function, possibly by deacetylation (PubMed:16892051). Involved in HES1- and HEY2-mediated transcriptional repression (PubMed:12535671). In cooperation with MYCN seems to be involved in transcriptional repression of DUSP6/MAPK3 leading to MYCN stabilization by phosphorylation at 'Ser-62' (PubMed:21698133). Deacetylates MEF2D (PubMed:16166628). Required for antagonist-mediated transcription suppression of AR-dependent genes which may be linked to local deacetylation of histone H3 (PubMed:17505061). Represses HNF1A-mediated transcription (By similarity). Required for the repression of ESRRG by CREBZF (PubMed:19690166). Deacetylates NR1H3 and NR1H2 and deacetylation of NR1H3 at 'Lys-434' positively regulates transcription of NR1H3:RXR target genes, promotes NR1H3 proteasomal degradation and results in cholesterol efflux; a promoter clearing mechanism after reach round of transcription is proposed (PubMed:17936707). Involved in lipid metabolism: deacetylates LPIN1, thereby inhibiting diacylglycerol synthesis (PubMed:20817729, PubMed:29765047). Implicated in regulation of adipogenesis and fat mobilization in white adipocytes by repression of PPARG which probably involves association with NCOR1 and SMRT/NCOR2 (By similarity). Deacetylates p300/EP300 and PRMT1 (By similarity). Deacetylates ACSS2 leading to its activation, and HMGCS1 deacetylation (PubMed:21701047). Involved in liver and muscle metabolism. Through deacetylation and activation of PPARGC1A is required to activate fatty acid oxidation in skeletal muscle under low-glucose conditions and is involved in glucose homeostasis (PubMed:23142079). Involved in regulation of PPARA and fatty acid beta-oxidation in liver. Involved in positive regulation of insulin secretion in pancreatic beta cells in response to glucose; the function seems to imply transcriptional repression of UCP2. Proposed to deacetylate IRS2 thereby facilitating its insulin-induced tyrosine phosphorylation. Deacetylates SREBF1 isoform SREBP-1C thereby decreasing its stability and transactivation in lipogenic gene expression (PubMed:17290224, PubMed:20817729). Involved in DNA damage response by repressing genes which are involved in DNA repair, such as XPC and TP73, deacetylating XRCC6/Ku70, and facilitating recruitment of additional factors to sites of damaged DNA, such as SIRT1-deacetylated NBN can recruit ATM to initiate DNA repair and SIRT1-deacetylated XPA interacts with RPA2 (PubMed:15205477, PubMed:16998810, PubMed:17334224, PubMed:17612497, PubMed:20670893, PubMed:21149730). Also involved in DNA repair of DNA double-strand breaks by homologous recombination and specifically single-strand annealing independently of XRCC6/Ku70 and NBN (PubMed:15205477, PubMed:17334224, PubMed:20097625). Promotes DNA double-strand breaks by mediating deacetylation of SIRT6 (PubMed:32538779). Transcriptional suppression of XPC probably involves an E2F4:RBL2 suppressor complex and protein kinase B (AKT) signaling. Transcriptional suppression of TP73 probably involves E2F4 and PCAF. Deacetylates WRN thereby regulating its helicase and exonuclease activities and regulates WRN nuclear translocation in response to DNA damage (PubMed:18203716). Deacetylates APEX1 at 'Lys-6' and 'Lys-7' and stimulates cellular AP endonuclease activity by promoting the association of APEX1 to XRCC1 (PubMed:19934257). Catalyzes deacetylation of ERCC4/XPF, thereby impairing interaction with ERCC1 and nucleotide excision repair (NER) (PubMed:32034146). Increases p53/TP53-mediated transcription-independent apoptosis by blocking nuclear translocation of cytoplasmic p53/TP53 and probably redirecting it to mitochondria. Deacetylates XRCC6/Ku70 at 'Lys-539' and 'Lys-542' causing it to sequester BAX away from mitochondria thereby inhibiting stress-induced apoptosis. Is involved in autophagy, presumably by deacetylating ATG5, ATG7 and MAP1LC3B/ATG8 (PubMed:18296641). Deacetylates AKT1 which leads to enhanced binding of AKT1 and PDK1 to PIP3 and promotes their activation (PubMed:21775285). Acts as a regulator of AMPK activity in response to calorie restriction: deacetylates the ATP6V1E1 subunit of the V-ATPase complex following activation by TULP3, leading to (1) V-ATPase complex inhibition on lysosomes and (2) AMPK activation via the AXIN1-STK11/LKB1 axis (By similarity). Proposed to play role in regulation of STK11/LBK1-dependent AMPK signaling pathways implicated in cellular senescence which seems to involve the regulation of the acetylation status of STK11/LBK1. Can deacetylate STK11/LBK1 and thereby increase its activity, cytoplasmic localization and association with STRAD; however, the relevance of such activity in normal cells is unclear (PubMed:18687677, PubMed:20203304). In endothelial cells is shown to inhibit STK11/LBK1 activity and to promote its degradation. Deacetylates SMAD7 at 'Lys-64' and 'Lys-70' thereby promoting its degradation. Deacetylates CIITA and augments its MHC class II transactivation and contributes to its stability (PubMed:21890893). Deacetylates MECOM/EVI1 (PubMed:21555002). Deacetylates PML at 'Lys-487' and this deacetylation promotes PML control of PER2 nuclear localization (PubMed:22274616). During the neurogenic transition, represses selective NOTCH1-target genes through histone deacetylation in a BCL6-dependent manner and leading to neuronal differentiation. Regulates the circadian expression of several core clock genes, including BMAL1, RORC, PER2 and CRY1 and plays a critical role in maintaining a controlled rhythmicity in histone acetylation, thereby contributing to circadian chromatin remodeling (PubMed:18662546). Deacetylates BMAL1 and histones at the circadian gene promoters in order to facilitate repression by inhibitory components of the circadian oscillator (By similarity). Deacetylates PER2, facilitating its ubiquitination and degradation by the proteasome (By similarity). Protects cardiomyocytes against palmitate-induced apoptosis (By similarity). Deacetylates XBP1 isoform 2; deacetylation decreases protein stability of XBP1 isoform 2 and inhibits its transcriptional activity (PubMed:20955178). Deacetylates PCK1 and directs its activity toward phosphoenolpyruvate production promoting gluconeogenesis (PubMed:30193097). Involved in the CCAR2-mediated regulation of PCK1 and NR1D1 (PubMed:24415752). Deacetylates CTNB1 at 'Lys-49' (PubMed:24824780). In POMC (pro-opiomelanocortin) neurons, required for leptin-induced activation of PI3K signaling (By similarity). Deacetylates SOX9; promoting SOX9 nuclear localization and transactivation activity (By similarity). Involved in the regulation of centrosome duplication: deacetylates CENATAC in G1 phase, allowing for SASS6 accumulation on the centrosome and subsequent procentriole assembly (PubMed:31722219). Deacetylates NDC80/HEC1 (PubMed:30409912). In addition to protein deacetylase activity, also acts as a protein-lysine deacylase by mediating protein delactylation, depropionylation and decrotonylation (PubMed:28497810, PubMed:38512451). Mediates depropionylation of Osterix (SP7) (By similarity). Catalyzes decrotonylation of histones; it however does not represent a major histone decrotonylase (PubMed:28497810). Mediates protein delactylation of TEAD1 and YAP1 (PubMed:38512451)\nDeacetylates 'Lys-382' of p53/TP53, however with lower activity than isoform 1. In combination, the two isoforms exert an additive effect. Isoform 2 regulates p53/TP53 expression and cellular stress response and is in turn repressed by p53/TP53 presenting a SIRT1 isoform-dependent auto-regulatory loop\nCatalytically inactive 75SirT1 may be involved in regulation of apoptosis. May be involved in protecting chondrocytes from apoptotic death by associating with cytochrome C and interfering with apoptosome assembly\n(Microbial infection) In case of HIV-1 infection, interacts with and deacetylates the viral Tat protein. The viral Tat protein inhibits SIRT1 deacetylation activity toward RELA/NF-kappa-B p65, thereby potentiates its transcriptional activity and SIRT1 is proposed to contribute to T-cell hyperactivation during infection","source":"project UniProt records20261017/18"},{"partner":"SPEN","hgnc":"HGNC:17575","core":true,"core_annotation":{"hgnc":"HGNC:17575","symbol_at_source":"SPEN","accession":"Q96T58","function":"Histone modification erase cofactor, TF","target":"histone","pmids":["11331609"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":136,"hub_weight":0.5184758473652126,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May serve as a nuclear matrix platform that organizes and integrates transcriptional responses. In osteoblasts, supports transcription activation: synergizes with RUNX2 to enhance FGFR2-mediated activation of the osteocalcin FGF-responsive element (OCFRE) (By similarity). Has also been shown to be an essential corepressor protein, which probably regulates different key pathways such as the Notch pathway. Negative regulator of the Notch pathway via its interaction with RBPSUH, which prevents the association between NOTCH1 and RBPSUH, and therefore suppresses the transactivation activity of Notch signaling. Blocks the differentiation of precursor B-cells into marginal zone B-cells. Probably represses transcription via the recruitment of large complexes containing histone deacetylase proteins. May bind both to DNA and RNA","source":"project UniProt records20261017/18"},{"partner":"PPP4R2","hgnc":"HGNC:18296","core":true,"core_annotation":{"hgnc":"HGNC:18296","symbol_at_source":"PPP4R2","accession":"Q9NY27","function":"Histone modification cofactor","target":"histone","pmids":["18614045"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":93,"hub_weight":0.5913123959890826,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers. Its interaction with the SMN complex leads to enhance the temporal localization of snRNPs, suggesting a role of PPP4C in maturation of spliceosomal snRNPs. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Mediates RPA2 dephosphorylation by recruiting PPP4C to RPA2 in a DNA damage-dependent manner. RPA2 dephosphorylation is required for the efficient RPA2-mediated recruitment of RAD51 to chromatin following double strand breaks, an essential step for DNA repair","source":"project UniProt records20261017/18"},{"partner":"JMJD6","hgnc":"HGNC:19355","core":true,"core_annotation":{"hgnc":"HGNC:19355","symbol_at_source":"JMJD6","accession":"Q6NYC1","function":"Histone modification erase","target":"histone","pmids":["17947579"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":197,"hub_weight":0.44992127066584753,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleoplasm; Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Dioxygenase that can both act as a arginine demethylase and a lysyl-hydroxylase (PubMed:17947579, PubMed:20684070, PubMed:21060799, PubMed:22189873, PubMed:24498420). Acts as a lysyl-hydroxylase that catalyzes 5-hydroxylation on specific lysine residues of target proteins such as U2AF2/U2AF65 and LUC7L2. Regulates RNA splicing by mediating 5-hydroxylation of U2AF2/U2AF65, affecting the pre-mRNA splicing activity of U2AF2/U2AF65 (PubMed:19574390). Hydroxylates its own N-terminus, which is required for homooligomerization (PubMed:22189873). Plays a role in the regulation of nucleolar liquid-liquid phase separation (LLPS) by post-translationally modifying LIAT1 at its lysine-rich domain which inhibits LIAT1 nucleolar targeting (By similarity). In addition to peptidyl-lysine 5-dioxygenase activity, may act as an RNA hydroxylase, as suggested by its ability to bind single strand RNA (PubMed:20679243, PubMed:29176719). Also acts as an arginine demethylase which preferentially demethylates asymmetric dimethylation (PubMed:17947579, PubMed:24360279, PubMed:24498420). Demethylates histone H3 at 'Arg-2' (H3R2me) and histone H4 at 'Arg-3' (H4R3me), including mono-, symmetric di- and asymmetric dimethylated forms, thereby playing a role in histone code (PubMed:17947579, PubMed:24360279). However, histone arginine demethylation may not constitute the primary activity in vivo (PubMed:17947579, PubMed:21060799, PubMed:22189873). In collaboration with BRD4, interacts with the positive transcription elongation factor b (P-TEFb) complex in its active form to regulate polymerase II promoter-proximal pause release for transcriptional activation of a large cohort of genes. On distal enhancers, so called anti-pause enhancers, demethylates both histone H4R3me2 and the methyl cap of 7SKsnRNA leading to the dismissal of the 7SKsnRNA:HEXIM1 inhibitor complex. After removal of repressive marks, the complex BRD4:JMJD6 attract and retain the P-TEFb complex on chromatin, leading to its activation, promoter-proximal polymerase II pause release, and transcriptional activation (PubMed:24360279). Demethylates other arginine methylated-proteins such as ESR1 (PubMed:24498420). Has no histone lysine demethylase activity (PubMed:21060799). Required for differentiation of multiple organs during embryogenesis. Acts as a key regulator of hematopoietic differentiation: required for angiogenic sprouting by regulating the pre-mRNA splicing activity of U2AF2/U2AF65 (By similarity). Seems to be necessary for the regulation of macrophage cytokine responses (PubMed:15622002)","source":"project UniProt records20261017/18"},{"partner":"CHD8","hgnc":"HGNC:20153","core":true,"core_annotation":{"hgnc":"HGNC:20153","symbol_at_source":"CHD8","accession":"Q9HCK8","function":"Chromatin remodeling","target":"chromatin","pmids":["18378692"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":375,"hub_weight":0.3429971702850177,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor, it slides nucleosomes along DNA; nucleosome sliding requires ATP (PubMed:28533432). Acts as a transcription repressor by remodeling chromatin structure and recruiting histone H1 to target genes. Suppresses p53/TP53-mediated apoptosis by recruiting histone H1 and preventing p53/TP53 transactivation activity. Acts as a negative regulator of Wnt signaling pathway by regulating beta-catenin (CTNNB1) activity. Negatively regulates CTNNB1-targeted gene expression by being recruited specifically to the promoter regions of several CTNNB1 responsive genes. Involved in both enhancer blocking and epigenetic remodeling at chromatin boundary via its interaction with CTCF. Acts as a suppressor of STAT3 activity by suppressing the LIF-induced STAT3 transcriptional activity. Also acts as a transcription activator via its interaction with ZNF143 by participating in efficient U6 RNA polymerase III transcription. Regulates alternative splicing of a core group of genes involved in neuronal differentiation, cell cycle and DNA repair. Enables H3K36me3-coupled transcription elongation and co-transcriptional RNA processing likely via interaction with HNRNPL","source":"project UniProt records20261017/18"},{"partner":"PPP4R3A","hgnc":"HGNC:20219","core":true,"core_annotation":{"hgnc":"HGNC:20219","symbol_at_source":"SMEK1","accession":"Q6IN85","function":"Histone modification erase cofactor","target":"histone","pmids":["18614045"],"complexes":"PPP4C-PPP4R2-PPP4R3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":142,"hub_weight":0.5103103630798288,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4. May regulate the activity of PPP4C at centrosomal microtubule organizing centers. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA DSB repair","source":"project UniProt records20261017/18"},{"partner":"PHF14","hgnc":"HGNC:22203","core":true,"core_annotation":{"hgnc":"HGNC:22203","symbol_at_source":"PHF14","accession":"O94880","function":"Histone modification read","target":"histone","pmids":["23688586"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone-binding protein (PubMed:23688586). Binds preferentially to unmodified histone H3 but can also bind to a lesser extent to histone H3 trimethylated at 'Lys-9' (H3K9me3) as well as to histone H3 monomethylated at 'Lys-27' (H3K27ac) and trimethylated at 'Lys-27' (H3K27me3) (By similarity). Represses PDGFRA expression, thus playing a role in regulation of mesenchymal cell proliferation (By similarity). Suppresses the expression of CDKN1A/p21 by reducing the level of trimethylation of histone H3 'Lys-4', leading to enhanced proliferation of germinal center B cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CXXC1","hgnc":"HGNC:24343","core":true,"core_annotation":{"hgnc":"HGNC:24343","symbol_at_source":"CXXC1","accession":"Q9P0U4","function":"Chromatin remodeling, TF","target":"DNA","pmids":["21407193"],"complexes":"COMPASS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":110,"hub_weight":0.5590169943749475,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus speckle; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional activator that exhibits a unique DNA binding specificity for CpG unmethylated motifs with a preference for CpGG","source":"project UniProt records20261017/18"},{"partner":"CHD9","hgnc":"HGNC:25701","core":true,"core_annotation":{"hgnc":"HGNC:25701","symbol_at_source":"CHD9","accession":"Q3L8U1","function":"Chromatin remodeling","target":"DNA","pmids":["16554032"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":64,"hub_weight":0.6622661785325219,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Probable ATP-dependent chromatin-remodeling factor. Acts as a transcriptional coactivator for PPARA and possibly other nuclear receptors. Has DNA-dependent ATPase activity and binds to A/T-rich DNA. Associates with A/T-rich regulatory regions in promoters of genes that participate in the differentiation of progenitors during osteogenesis (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SETD1A","hgnc":"HGNC:29010","core":true,"core_annotation":{"hgnc":"HGNC:29010","symbol_at_source":"SETD1A","accession":"O15047","function":"Histone modification write","target":"histone","pmids":["17355966"],"complexes":"COMPASS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":140,"hub_weight":0.512989176042577,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Nucleus speckle; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that catalyzes methyl group transfer from S-adenosyl-L-methionine to the epsilon-amino group of 'Lys-4' of histone H3 (H3K4) via a non-processive mechanism (PubMed:12670868, PubMed:25561738). Part of chromatin remodeling machinery, forms H3K4me1, H3K4me2 and H3K4me3 methylation marks at active chromatin sites where transcription and DNA repair take place (PubMed:29937342, PubMed:31197650, PubMed:32346159). Responsible for H3K4me3 enriched promoters and transcriptional programming of inner mass stem cells and neuron progenitors during embryogenesis (By similarity) (PubMed:31197650). Required for H3K4me1 mark at stalled replication forks. Mediates FANCD2-dependent nucleosome remodeling and RAD51 nucleofilaments stabilization at reversed forks, protecting them from nucleolytic degradation (PubMed:29937342, PubMed:32346159). Does not methylate 'Lys-4' of histone H3 if the neighboring 'Lys-9' residue is already methylated (PubMed:12670868). Binds RNAs involved in RNA processing and the DNA damage response (PubMed:38003223)","source":"project UniProt records20261017/18"},{"partner":"PPP4R3B","hgnc":"HGNC:29267","core":true,"core_annotation":{"hgnc":"HGNC:29267","symbol_at_source":"SMEK2","accession":"Q5MIZ7","function":"Histone modification erase cofactor","target":"histone","pmids":["18614045"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":58,"hub_weight":0.6804138174397717,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"CT45A1","accession":"Q5HYN5","identity":0.989,"qcov":1.0,"tcov":1.0,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"CT47A2":{"coreEvidence":[],"near_known_relatives":[]},"CT47A3":{"coreEvidence":[],"near_known_relatives":[]},"CT47A4":{"coreEvidence":[],"near_known_relatives":[]},"CT47A5":{"coreEvidence":[],"near_known_relatives":[]},"CT47A6":{"coreEvidence":[],"near_known_relatives":[]},"CT47A7":{"coreEvidence":[],"near_known_relatives":[]},"CT47A8":{"coreEvidence":[],"near_known_relatives":[]},"CT47A9":{"coreEvidence":[],"near_known_relatives":[]},"CT47A10":{"coreEvidence":[],"near_known_relatives":[]},"CT47A12":{"coreEvidence":[],"near_known_relatives":[]},"TRIM49D2":{"coreEvidence":[],"near_known_relatives":[]},"TRIM49D1":{"coreEvidence":[],"near_known_relatives":[]},"FAM156B":{"coreEvidence":[{"partner":"GADD45G","hgnc":"HGNC:4097","core":true,"core_annotation":{"hgnc":"HGNC:4097","symbol_at_source":"GADD45G","accession":"O95257","function":"Chromatin remodeling","target":"histone","pmids":["21986581"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":57,"hub_weight":0.6835859270246633,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Involved in the regulation of growth and apoptosis. Mediates activation of stress-responsive MTK1/MEKK4 MAPKKK","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
